from threetears.evals import Eval

from mdtable import format_table

def write_table(case):
    """The Markdown the handbook gets for the table."""
    return {"markdown": format_table(case["header"], case["rows"], case.get("align"))}


def as_signed_off(case, out):
    """The table is written as the signed-off Markdown."""
    return out["markdown"] == case["expected"]

tables = Eval("data/tables.jsonl", runner=write_table, grader=[as_signed_off], k=1)
